/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const events = api.data.fetch_spokes.output ? api.data.fetch_spokes.output : [];
  return events.map(spoke => ({
    id: spoke,
    label: spoke
  }));
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const spokeUsage = (api.data.locale_get_list_spokes && api.data.locale_get_list_spokes.output) ? api.data.locale_get_list_spokes.output.spoke_usage : api.state.translateObject.spoke_usage;
    return `${api.state.selectedSpoke} ${spokeUsage}`;
}
